static void test_stuck()
{
    std::printf("T9 SDA stuck low: <=9 clocks while watching SDA, STOP, re-init\n");
    int good = 0;
    for (uint32_t k = 1; k <= 9; k++) {
        Rig g;
        CHECK(g.drv.init(g.now()), "init");
        for (int i = 0; i < 4; i++) g.step(P0, T0);
        g.bus.stuck_clocks = k;
        const uint32_t pulses0 = g.bus.clock_pulses, stops0 = g.bus.stops;
        int first_ok = -1;
        for (int i = 0; i < 10 && first_ok < 0; i++) if (g.step(P0, T0) == Update::NEW_SAMPLE) first_ok = i;
        const Health& h = g.drv.health();
        const bool ok = h.recoveries == 1 && h.last_clear_clocks == k && g.bus.clock_pulses - pulses0 == k &&
                        g.bus.stops - stops0 == 1 && first_ok >= 0 && first_ok <= 2 && h.sda_stuck_seen >= 1;
        CHECK(ok, "k=%u rec=%u clocks=%u pulses=%u stops=%u first=%d", unsigned(k), unsigned(h.recoveries),
              unsigned(h.last_clear_clocks), unsigned(g.bus.clock_pulses - pulses0), unsigned(g.bus.stops - stops0), first_ok);
        if (ok) good++;
    }
    std::printf("      k = 1..9 held clocks: %d/9 cleared with exactly k pulses, STOP on SDA with SCL high, 1 STOP each\n", good);
    {   // hard stuck: 9 clocks, fail, holdoff, then heals
        Rig g;
        CHECK(g.drv.init(g.now()), "init");
        g.bus.stuck_clocks = 2000000;
        int nr = 0;
        for (int i = 0; i < 8; i++) if (g.step(P0, T0) != Update::NEW_SAMPLE) nr++;
        const Health& h = g.drv.health();
        CHECK(h.recovery_failed >= 1 && h.last_clear_clocks == 9 && (h.flags & F_RECOVERY_FAIL) && nr == 8,
              "hard stuck failed=%u clocks=%u", unsigned(h.recovery_failed), unsigned(h.last_clear_clocks));
        CHECK(g.drv.state() == DriverState::HOLDOFF, "holdoff");
        const uint32_t attempts = h.recoveries;
        g.bus.stuck_clocks = 0;   // e.g. GPS cable unplugged / compass power-cycled
        int first_ok = -1;
        for (int i = 0; i < 12 && first_ok < 0; i++) if (g.step(P0, T0) == Update::NEW_SAMPLE) first_ok = i;
        CHECK(first_ok >= 0 && !(g.drv.health().flags & F_RECOVERY_FAIL), "heals after holdoff");
        std::printf("      hard stuck: 9 clocks, %u failed recoveries in 250 ms (holdoff), healed %d samples after release\n",
                    unsigned(attempts), first_ok + 1);
    }
}

// The pre-Rev-12 bus clear, kept verbatim as a simulator sensitivity check:
// stop clocking at the first SDA high, then STOP via SCL low / SDA low / SCL
// high / SDA high.
static bool legacy_recover(I2cBusGpio& g, uint32_t& clocks)
{
    const uint32_t hp = 5;
    g.begin_bitbang();
    g.set_sda(true); g.set_scl(true); g.delay_us(hp);
    bool ok = g.read_scl();
    clocks = 0;
    while (ok && !g.read_sda() && clocks < 9) {
        g.set_scl(false); g.delay_us(hp); g.set_scl(true); ok = g.read_scl(); g.delay_us(hp); clocks++;
    }
    if (ok) {
        g.set_scl(false); g.delay_us(hp); g.set_sda(false); g.delay_us(hp);
        g.set_scl(true); ok = g.read_scl(); g.delay_us(hp); g.set_sda(true); g.delay_us(hp);
        ok = ok && g.read_sda() && g.read_scl();
    }
    g.end_bitbang();
    return ok;
}

static void test_stuck_bitlevel()
{
    std::printf("T9b bus clear vs a bit-level slave hung mid-READ / mid-WRITE ACK / mid-address\n");
    static const char* const names[4] = {"", "read (slave TX)", "write (slave RX)", "address (after START)"};
    {   // the reproduced field failure: remaining bits 0,0,1,0
        Rig g;
        g.bus.hang(BitSlave::TX, 4, 0x02, true, false);
        uint32_t clk = 0;
        const uint32_t st0 = g.bus.stops;
        const bool r = legacy_recover(g.bus, clk);
        CHECK(!r && clk == 2 && g.bus.stops - st0 == 0 && g.bus.bs.in_txn,
              "legacy repro r=%d clocks=%u stops=%u", int(r), unsigned(clk), unsigned(g.bus.stops - st0));
        g.bus.hang(BitSlave::TX, 4, 0x02, true, false);
        const uint32_t p0 = g.bus.clock_pulses, s0 = g.bus.stops;
        const bool n = g.drv.recover_bus();
        CHECK(n && g.drv.health().last_clear_clocks == 2 && g.bus.clock_pulses - p0 == 2 && g.bus.stops - s0 == 1 &&
              !g.bus.bs.in_txn && g.bus.bs.mode == BitSlave::IDLE, "new repro");
        std::printf("      bits 0,0,1,0 left (TX pos 4, 0x02): legacy %s after %u clocks, %u STOP; new %s, %u clocks, 1 STOP\n",
                    r ? "OK" : "FAILS", unsigned(clk), unsigned(g.bus.stops - st0 > 0), n ? "OK" : "FAIL",
                    unsigned(g.drv.health().last_clear_clocks));
    }
    Rig g;
    uint32_t cases = 0, good = 0, legacy_fail = 0, worst[4] = {0, 0, 0, 0}, n_mode[4] = {0, 0, 0, 0};
    uint32_t total_clocks = 0;
    for (int m = BitSlave::TX; m <= BitSlave::ADDR; m++) {
        const BitSlave::Mode mode = BitSlave::Mode(m);
        for (uint8_t pos = 0; pos <= 8; pos++) {
            for (unsigned b = 0; b < 256; b++) {
                for (int scl_low = 0; scl_low < 2; scl_low++) {
                    // the master can only have been driving SDA low in its own read-ACK slot
                    const int msda_n = (mode == BitSlave::TX && pos == 8) ? 2 : 1;
                    for (int msda = 0; msda < msda_n; msda++) {
                        cases++;
                        n_mode[m]++;
                        g.bus.hang(mode, pos, uint8_t(b), scl_low != 0, msda != 0);
                        const uint32_t p0 = g.bus.clock_pulses, s0 = g.bus.stops;
                        const bool r = g.drv.recover_bus();
                        const uint32_t clk = g.drv.health().last_clear_clocks, pulses = g.bus.clock_pulses - p0;
                        const bool ok = r && clk <= 9 && pulses == clk && g.bus.stops - s0 >= 1 &&
                                        !g.bus.bs.in_txn && g.bus.bs.mode == BitSlave::IDLE &&
                                        g.bus.read_sda() && g.bus.read_scl() &&
                                        !(g.drv.health().flags & F_RECOVERY_FAIL);
                        if (ok) good++;
                        else if (good + 50 > cases)   // print only the first few
                            CHECK(false, "%s pos=%u byte=0x%02X scl_low=%d msda=%d r=%d clocks=%u pulses=%u stops=%u in_txn=%d",
                                  names[m], unsigned(pos), b, scl_low, msda, int(r), unsigned(clk), unsigned(pulses),
                                  unsigned(g.bus.stops - s0), int(g.bus.bs.in_txn));
                        if (clk > worst[m]) worst[m] = clk;
                        total_clocks += clk;
                        // same state through the pre-Rev-12 sequence
                        g.bus.hang(mode, pos, uint8_t(b), scl_low != 0, msda != 0);
                        uint32_t lc = 0;
                        const bool lr = legacy_recover(g.bus, lc);
                        if (!lr || g.bus.bs.in_txn) legacy_fail++;
                    }
                }
            }
        }
    }
    CHECK(good == cases, "bit-level recovery %u/%u", unsigned(good), unsigned(cases));
    CHECK(worst[BitSlave::TX] == 8 && worst[BitSlave::RX] == 1 && worst[BitSlave::ADDR] == 1,
          "worst clocks TX %u RX %u ADDR %u", unsigned(worst[1]), unsigned(worst[2]), unsigned(worst[3]));
    CHECK(legacy_fail > 0, "simulator must expose the pre-Rev-12 STOP bug");
    for (int m = BitSlave::TX; m <= BitSlave::ADDR; m++)
        std::printf("      %-22s %5u states (pos 0..8 x 256 bytes x SCL low/high%s): worst %u clocks\n", names[m],
                    unsigned(n_mode[m]), m == BitSlave::TX ? " x master ACK" : "", unsigned(worst[m]));
    std::printf("      %u/%u recovered, STOP seen by slave, bus idle, <= 9 clocks (mean %.2f); legacy sequence fails %u/%u\n",
                unsigned(good), unsigned(cases), double(total_clocks) / cases, unsigned(legacy_fail), unsigned(cases));
}

static void test_spikes()
{
    std::printf("T10 plausibility: range, isolated spikes, real 3 m step, 30 m/s climb\n");
    Rig g;
    CHECK(g.drv.init(g.now()), "init");
    double P = P0;
    for (int i = 0; i < 10; i++) g.step(P + 0.5 * nrand(), T0);
    // isolated corrupted samples: flip one bit in the PSR burst (bits 6..23 of the 24-bit word)
    int injected = 0, leaked = 0, small_leak = 0;
    for (int i = 0; i < 400; i++) {
        const bool inj = (i % 7) == 3;
        if (inj) {
            const uint32_t bitpos = 6 + irand(18);   // 0..23 from LSB
            g.bus.add_flip(true, reg::PSR_B2, g.bus.read_occ[reg::PSR_B2] + 1, uint8_t(2 - bitpos / 8), uint8_t(bitpos % 8));
            injected++;
        }
        const double pt = P + 0.5 * nrand();
        if (g.step(pt, T0) == Update::NEW_SAMPLE && inj) {
            const double e = std::fabs(g.drv.last().pressure_pa - pt);
            if (e > 31.0) leaked++; else small_leak++;
        }
        if (g.bus.nflips > 48) g.bus.clear_flips();
    }
    const Health& h = g.drv.health();
    std::printf("      %d corrupted samples: %d accepted with error > gate, %d accepted below gate (bits 6-7 of LSB)\n",
                injected, leaked, small_leak);
    CHECK(leaked == 0, "leaked %d", leaked);
    // real 3 m climb as a step (-36 Pa)
    const double step = -3.0 * 12.01;
    P += step;
    int follow = -1;
    for (int i = 0; i < 10 && follow < 0; i++) {
        if (g.step(P + 0.5 * nrand(), T0) == Update::NEW_SAMPLE && std::fabs(g.drv.last().pressure_pa - P) < 3) follow = i + 1;
    }
    CHECK(follow >= 1 && follow <= g.cfg.reanchor_samples, "3 m step followed in %d samples", follow);
    std::printf("      3 m step (%.1f Pa): followed after %d samples (%.0f ms), reanchors=%u\n", step, follow,
                follow * 31.25, unsigned(h.reanchors));
    // a 10 m step (120 Pa) is outside even the widened gate: only the re-anchor rule can follow it
    const uint32_t ra0 = h.reanchors;
    P -= 10.0 * 12.01;
    follow = -1;
    for (int i = 0; i < 10 && follow < 0; i++) if (g.step(P + 0.5 * nrand(), T0) == Update::NEW_SAMPLE && std::fabs(g.drv.last().pressure_pa - P) < 3) follow = i + 1;
    CHECK(follow == g.cfg.reanchor_samples && h.reanchors == ra0 + 1, "10 m step followed in %d", follow);
    std::printf("      10 m step (%.0f Pa): re-anchored after %d consistent samples (%.0f ms)\n", -10 * 12.01, follow, follow * 31.25);
    // a spike immediately before a real step must not latch the filter out
    g.bus.add_flip(true, reg::PSR_B2, g.bus.read_occ[reg::PSR_B2] + 1, 0, 3);
    g.step(P, T0);
    P -= 36.0;
    follow = -1;
    for (int i = 0; i < 10 && follow < 0; i++) if (g.step(P + 0.5 * nrand(), T0) == Update::NEW_SAMPLE && std::fabs(g.drv.last().pressure_pa - P) < 3) follow = i + 1;
    CHECK(follow >= 1 && follow <= g.cfg.reanchor_samples, "spike+step followed in %d", follow);
    // sustained 30 m/s climb: every sample accepted
    const uint32_t rej0 = h.rej_rate;
    int acc = 0;
    for (int i = 0; i < 64; i++) {
        P -= 30.0 * 12.01 * 0.03125;
        if (g.step(P + 0.5 * nrand(), T0) == Update::NEW_SAMPLE) acc++;
    }
    CHECK(acc == 64 && h.rej_rate == rej0, "30 m/s climb acc=%d rej=%u", acc, unsigned(h.rej_rate - rej0));
    std::printf("      30 m/s climb for 2 s: %d/64 accepted, 0 rate rejections\n", acc);
    // range limits
    Rig r2;
    CHECK(r2.drv.init(r2.now()), "init");
    for (int i = 0; i < 5; i++) r2.step(P0, T0);
    const Update lo = r2.step(29000.0, T0);
    const Update hi = r2.step(121000.0, T0);
    CHECK(lo == Update::REJECTED && hi == Update::REJECTED && r2.drv.health().rej_range_p == 2, "range");
    r2.dev.r[reg::PSR_B2] = 0;
    r2.step(P0, 95.0);
    CHECK(r2.drv.health().rej_range_t == 1, "temperature range");
}

static void test_soak()
{
    std::printf("T11 soak: 20000 samples, random SDA noise + NACK/ARB/BERR + stuck + POR\n");
    Rig g;
    g.bus.ber = 2e-4;  g.bus.p_nack = 0.01; g.bus.p_arb = 0.003; g.bus.p_berr = 0.003;
    g.bus.p_addr = 0.002; g.bus.p_stuck = 0.0005; g.bus.p_por = 0.0002;
    g.drv.init(g.now());
    double P = P0, v = 0, worst = 0;
    int acc = 0, over2 = 0, coef_bad = 0;
    for (int i = 0; i < 20000; i++) {
        v += 0.3 * nrand();
        if (v > 10) v = 10;
        if (v < -10) v = -10;
        P -= v * 12.01 * 0.03125;
        if (P < 90000 || P > 105000) v = -v;
        const double pt = P + 0.5 * nrand();
        if (g.step(pt, T0) == Update::NEW_SAMPLE) {
            acc++;
            const double e = std::fabs(g.drv.last().pressure_pa - pt);
            worst = std::fmax(worst, e);
            if (e > 2.0) over2++;
        }
        if ((g.drv.health().flags & F_COEF_VALID) && g.drv.coefficients() != known_coefs()) coef_bad++;
    }
    const Health& h = g.drv.health();
    std::printf("      faults: %u bit flips, %u stuck events (%u bit-level), %u POR; xfer ok %u, NACK %u, ARB %u, BERR %u, TO %u, retries %u\n",
                unsigned(g.bus.rnd_flips), unsigned(g.bus.rnd_stuck), unsigned(g.bus.rnd_bit_hangs), unsigned(g.bus.rnd_por), unsigned(h.xfer_ok),
                unsigned(h.nack), unsigned(h.arb_lost), unsigned(h.bus_error), unsigned(h.timeout), unsigned(h.retries));
    std::printf("      recoveries %u (failed %u), config lost/repaired %u/%u, coef mismatches %u, rejections rate/range/pattern %u/%u/%u\n",
                unsigned(h.recoveries), unsigned(h.recovery_failed), unsigned(h.config_lost), unsigned(h.config_repairs),
                unsigned(h.coef_mismatch), unsigned(h.rej_rate), unsigned(h.rej_range_p + h.rej_range_t), unsigned(h.rej_pattern));
    std::printf("      accepted %d/20000 (%.2f %%), worst |error| %.1f Pa, %d (%.3f %%) > 2 Pa\n", acc, acc / 200.0, worst,
                over2, over2 * 100.0 / (acc ? acc : 1));
    CHECK(coef_bad == 0, "coefficients corrupted %d", coef_bad);
    CHECK(acc > 18000, "availability %d", acc);
    CHECK(worst < 40.0, "worst %f", worst);
    CHECK(over2 * 100.0 / (acc ? acc : 1) < 1.0, "over2 %d", over2);
    CHECK(h.recoveries >= g.bus.rnd_stuck && g.bus.rnd_stuck > 0, "every stuck event recovered");
    CHECK(g.bus.rnd_bit_hangs > 0 && !g.bus.bs.in_txn, "bit-level hangs %u cleared", unsigned(g.bus.rnd_bit_hangs));
}

int main()
{
    std::printf("Nano H743 AIO DPS310 robust driver tests (Rev 12.0)\n");
    test_bits();
    test_scale_budget();
    test_compensation();
    test_probe();
    test_init_sequence();
    test_coefficients();
    test_config_loss();
    test_nack();
    test_stuck();
    test_stuck_bitlevel();
    test_spikes();
    test_soak();
    std::printf("\nRESULT: %s (%d checks, %d failures)\n", g_fail ? "FAIL" : "PASS", g_pass + g_fail, g_fail);
    return g_fail ? 1 : 0;
}
